options.customCss:
@import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Sans+Arabic:wght@400;500;600;700&family=JetBrains+Mono:wght@500&display=swap');

:root{
  --ink:#e8eefb; --muted:#8ea3c2; --dim:#63799b;
  --panel:#0f1826; --field:#0a1220; --line:#1e2c42;
  --cyan:#22d3ee; --violet:#a78bfa;
}

body{
  background:
    radial-gradient(1100px 620px at 78% -12%, #1a2c4a 0%, rgba(7,12,21,0) 62%),
    radial-gradient(900px 520px at 8% 108%, #221a3d 0%, rgba(7,12,21,0) 60%),
    #070c15;
  background-attachment:fixed;
  color:var(--ink);
  font-family:'IBM Plex Sans Arabic', system-ui, sans-serif;
  padding:44px 18px;
}

.container{ max-width:700px; margin:0 auto; }

.card{
  background:var(--panel);
  border:1px solid var(--line);
  border-radius:20px;
  padding:36px 32px 30px;
  box-shadow:0 28px 70px rgba(0,0,0,.55);
  direction:rtl; text-align:right;
  position:relative; overflow:hidden;
}
.card::before{
  content:''; position:absolute; top:0; right:0; left:0; height:3px;
  background:linear-gradient(90deg, var(--cyan), var(--violet));
}

.form-header::before{
  content:'HW1 · MULTI-AGENT ARTICLE LAB';
  display:inline-block; direction:ltr;
  font-family:'JetBrains Mono', monospace; font-size:10.5px; letter-spacing:.16em;
  color:var(--cyan); background:rgba(34,211,238,.08);
  border:1px solid rgba(34,211,238,.32); border-radius:999px;
  padding:5px 11px; margin-bottom:16px;
}
.form-header h1{
  margin:0 0 10px; color:#fff; font-size:26px; font-weight:700; line-height:1.5;
}
.form-header p{
  margin:0; color:var(--muted); font-size:14px; line-height:1.95;
}
.form-header::after{
  content:'Intake → Lead Editor → Outline ⇄ Review → Article Writer ⇄ QA → Handover';
  display:block; direction:ltr; text-align:left;
  margin-top:20px; padding-top:16px; border-top:1px dashed var(--line);
  font-family:'JetBrains Mono', monospace; font-size:10px; letter-spacing:.05em;
  color:var(--dim);
}

.inputs-wrapper{ counter-reset: fld; margin-top:8px; }

.form-group{ counter-increment: fld; margin-top:24px; }

.form-label{
  display:flex; align-items:center; gap:9px;
  margin-bottom:9px; color:#cfdcef; font-size:13.5px; font-weight:600;
}
.form-label::before{
  content:counter(fld, decimal-leading-zero);
  font-family:'JetBrains Mono', monospace; font-size:10.5px;
  color:var(--violet); background:rgba(167,139,250,.12);
  border:1px solid rgba(167,139,250,.30); border-radius:7px;
  padding:3px 8px; line-height:1;
}
.form-label.form-required{ color:#cfdcef; }
.form-required::after{ color:var(--cyan); font-weight:700; }

.form-input, .select-input select, select, textarea{
  width:100%; box-sizing:border-box;
  background:var(--field); color:var(--ink);
  border:1px solid var(--line); border-radius:12px;
  padding:13px 15px; font-size:14.5px; font-family:inherit;
  direction:rtl; text-align:right;
  transition:border-color .15s ease, box-shadow .15s ease, background .15s ease;
}
textarea.form-input, textarea{ min-height:118px; line-height:1.9; resize:vertical; }

.form-input:focus, .select-input select:focus, select:focus, textarea:focus{
  outline:none; background:#0c1524;
  border-color:var(--cyan); box-shadow:0 0 0 3px rgba(34,211,238,.16);
}
.form-input::placeholder, textarea::placeholder{ color:#40567a; font-size:13.5px; }

.error-show{ color:#fb7185; font-size:12.5px; margin-top:6px; }

#submit-btn{
  width:100%; margin-top:30px; padding:15px;
  border:0; border-radius:13px; cursor:pointer;
  background:linear-gradient(90deg, var(--cyan), var(--violet));
  color:#05131c; font-family:inherit; font-size:15px; font-weight:700;
  letter-spacing:.01em;
  transition:filter .15s ease, transform .12s ease;
}
#submit-btn:hover{ filter:brightness(1.09); }
#submit-btn:active{ transform:translateY(1px); }

.test-notice{
  background:rgba(167,139,250,.10); border:1px solid rgba(167,139,250,.30);
  color:#c9b8ff; border-radius:12px; padding:10px 14px;
  font-size:12.5px; direction:rtl; text-align:right; margin-bottom:16px;
}
.n8n-link{ opacity:.35; font-size:11px; }
.n8n-link a{ color:var(--dim); }

#submitted-header{ color:#fff; font-size:22px; }
#submitted-content{ color:var(--muted); line-height:2; }

