options.customCss:
@import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Sans+Arabic:wght@400;600;700&family=Noto+Naskh+Arabic:wght@400;500;700&family=JetBrains+Mono:wght@500&display=swap');

:root{
  --paper:#fbfaf6; --paper-line:#e5e0d4;
  --text:#1c1c1a; --text-soft:#4a4a45;
  --cyan:#0e7490; --violet:#6d28d9;
}

body{
  background:
    radial-gradient(1000px 560px at 80% -10%, #1a2c4a 0%, rgba(7,12,21,0) 60%),
    #070c15;
  background-attachment:fixed;
  font-family:'IBM Plex Sans Arabic', system-ui, sans-serif;
  padding:44px 18px;
}

.container{ max-width:860px; margin:0 auto; }

#submitted-form, .card{
  background:var(--paper);
  border:1px solid var(--paper-line);
  border-radius:8px;
  padding:56px 60px 48px;
  box-shadow:0 34px 90px rgba(0,0,0,.55);
  direction:rtl; text-align:right;
  position:relative; overflow:hidden;
}
#submitted-form::before{
  content:'HW1 · MULTI-AGENT ARTICLE LAB — EDITOR-REVIEWED OUTPUT';
  display:block; direction:ltr; text-align:left;
  font-family:'JetBrains Mono', monospace; font-size:9.5px; letter-spacing:.18em;
  color:var(--cyan);
  padding-bottom:14px; margin-bottom:26px;
  border-bottom:2px solid var(--text);
}

#submitted-header{
  margin:0 0 10px;
  font-family:'Noto Naskh Arabic', serif;
  font-size:29px; font-weight:700; line-height:1.6; color:var(--text);
}

#submitted-form::after{
  content:'أُنتج هذا المقال آليًا عبر خمسة إيجنتات: Lead Editor · Outline Designer · Outline Reviewer · Article Writer · Quality Reviewer — مع حلقتَي مراجعة متكررتين حتى اعتماد الخطة التحريرية ثم اعتماد المسودة.';
  display:block; direction:rtl;
  font-size:11.5px; line-height:2.1; color:var(--text-soft);
  border-right:3px solid var(--violet); padding-right:12px;
  margin-top:34px; padding-top:2px;
}

#submitted-content{
  white-space:pre-wrap;
  font-family:'Noto Naskh Arabic', serif;
  font-size:16px; line-height:2.25; color:var(--text);
  text-align:justify;
  border-top:1px solid var(--paper-line);
  padding-top:28px;
}

.n8n-link{ opacity:.3; font-size:11px; }
.n8n-link a{ color:#63799b; }
.test-notice{
  background:rgba(167,139,250,.10); border:1px solid rgba(167,139,250,.30);
  color:#c9b8ff; border-radius:12px; padding:10px 14px;
  font-size:12.5px; direction:rtl; text-align:right; margin-bottom:16px;
}

@media print{
  body{ background:#fff !important; padding:0 !important; }
  .container{ max-width:none !important; }
  #submitted-form, .card{
    box-shadow:none !important; border:0 !important; border-radius:0 !important;
    padding:0 !important; background:#fff !important;
  }
  #submitted-content{ font-size:12.5pt; line-height:1.95; }
  #submitted-header{ font-size:20pt; }
  .test-notice, .n8n-link{ display:none !important; }
}
